import React from 'react';

const About = () => {
  return (
    <section id="about" style={{ padding: '50px 20px', maxWidth: '800px', margin: 'auto' }}>
      <h2>About Me</h2>
      <p>
        I am a recent Mobile Application Development graduate from Fanshawe College, Canada, 
        with a Bachelor’s in Computer Engineering. I have hands-on experience building mobile 
        and web apps using Swift, Kotlin, JavaScript, React, React Native, and Firebase.
      </p>
    </section>
  );
};

export default About;
